    });

    test('a known entry still carries the role past an unknown one', () {
      final resolver = _resolver(
        {
          'default': [
            ModelRef(provider: 'from-the-future', modelId: 'x'),
            ModelRef(provider: 'anthropic', modelId: 'claude-smol'),
