      cwd: cwd,
      homeDir: homeDir,
      onNotice: onNotice,
      now: now,
      jitterFraction: jitterFraction,
      sleeper: sleeper,
      streamFactory: streamFactory,
    );
  }

  /// The active configuration (replaced by [setDefaultChain]).
  ModelRolesConfig config;

  /// The saved custom providers (the `customProviders:` config section) —
